    def _changes_sig(self, names) -> str:
        """Hash of the registry's stat plus each shown project's STATUS.md mtime.

        Names map to paths through the registry, never from the request, so the
        page can only make the server stat STATUS files of real rows. mtime only:
        this runs every few seconds.
        """
        folders = {p["name"]: p.get("dev_folder") for p in self._load()["projects"]}
        parts = [self._fingerprint()]
        for name in sorted(set(names)):
            if name not in folders:
