                    mtime = os.stat(self.dev_root / folders[name] / "docs" / "STATUS.md").st_mtime_ns
                except OSError:
                    pass
            parts.append((name, mtime))
        return hashlib.sha1(json.dumps(parts).encode()).hexdigest()
