```js
// ---------- live polling: terminal edits reach the page (design Decision 2) ----------
// The server hashes the registry's stat plus the STATUS.md mtime of each project the
// page shows. A moved signature means reload. A change that lands while Eric is typing
// or dragging waits (pendingReload) instead of being dropped.
const POLL_MS = 3000;
let lastSig = null, pendingReload = false, dragging = false;
const busy = () => dragging ||
  (document.activeElement && document.activeElement.matches("input, textarea, select"));
function shownNames(){
  return REG ? REG.projects.filter(p => p.lane === lane).map(p => p.name) : [];
}
async function reloadIfIdle(){
  if(busy()){ pendingReload = true; return; }
  pendingReload = false;
  await load();
}
async function poll(){
  if(document.hidden || !REG) return;
  try {
    const names = shownNames().map(encodeURIComponent).join(",");
    const {sig} = await api("/api/changes?names=" + names);
    if(lastSig !== null && sig !== lastSig) await reloadIfIdle();
    lastSig = sig;
  } catch(e){ /* server stopped or restarting: stay quiet, try again next tick */ }
}
setInterval(poll, POLL_MS);
document.addEventListener("visibilitychange", () => { if(!document.hidden) poll(); });
document.addEventListener("dragstart", () => { dragging = true; });
document.addEventListener("dragend", () => { dragging = false; if(pendingReload) reloadIfIdle(); });
document.addEventListener("focusout", () => setTimeout(() => { if(pendingReload) reloadIfIdle(); }, 0));
```

Advancing `lastSig` on a deferred tick is safe because `pendingReload` carries the change.
Lane tabs set `lastSig = null` so a tab switch (different names) is a new baseline, not a
reload: in the tab `onclick`, add `lastSig = null;`.

