<body>
<header>
  <h1>Portfolio <em>Board</em></h1>
  <span id="meta"></span>
  <div class="tabs" id="tabs"></div>
  <button class="plain" id="undo">Undo</button>
</header>
<div id="app"></div>
<div class="flash" id="flash"></div>

<script>
const TOKEN = new URLSearchParams(location.search).get("token") || "";
const STAGES = ["idea","grilled","spec","planned","building","shipped"];
const STATUSES = ["active","paused","done","dropped","merged","archived"];
const ARCHIVED = new Set(["done","dropped","merged","archived"]);
// Mirrors portfolio.LANES. job counts against the slate cap; side is personal work.
const LANES = ["job","side","system","knowledge","tool"];
let REG = null, lane = "job", openCard = null;
const drafts = new Map();          // inbox name -> {purpose?, next_action?} draft edits not yet promoted

function applyDrafts(){
  (REG.inbox || []).forEach(r => {
    const d = drafts.get(r.name);
    if(d) Object.assign(r, d);
  });
}

function flash(msg){
  const f = document.getElementById("flash");
  f.textContent = msg; f.style.display = "block";
  clearTimeout(flash.t); flash.t = setTimeout(()=>f.style.display="none", 5000);
}
async function api(path, opts = {}){
  const sep = path.includes("?") ? "&" : "?";
  const res = await fetch(path + sep + "token=" + encodeURIComponent(TOKEN), {
    headers: {"Content-Type":"application/json"}, ...opts
  });
  if(!res.ok){
    let msg = res.statusText;
    try { msg = (await res.json()).error || msg; } catch {}
    throw new Error(msg);
  }
  return res.json();
}
function showBlocked(msg){
  const app = document.getElementById("app");
  app.textContent = "";
  const p = document.createElement("p");
  p.className = "blocked";
  p.textContent = "Cannot load the board: " + msg;
  app.append(p);
}
async function load(){
  try {
    REG = await api("/api/registry");
    applyDrafts();
    render();
  } catch(e){
    flash(e.message);
    if(!REG) showBlocked(e.message);
  }
}

// any failed write reloads from disk, so the board never shows a state that was not saved
async function write(path, payload, method = "POST"){
  let ok = true;
  try {
    const opts = {method};
    if(method !== "DELETE") opts.body = JSON.stringify(payload || {});
    await api(path, opts);
  } catch(e){
    ok = false;
    flash(e.message);
  }
  await load();          // load() handles its own errors, so a failed reload is never silent
  return ok;
}

const idx = s => Math.max(0, STAGES.indexOf(s));
const live = l => REG.projects
  .filter(p => p.lane === l && !ARCHIVED.has(p.status))
  .sort((a,b) => (a.rank||1e6) - (b.rank||1e6));

// Project names are one long word joined by underscores, so the browser has no break
// opportunity and cuts mid-syllable ("AT_Utilization_B / enchmarks"). Mark the joins
// with <wbr> instead. Built as nodes, not innerHTML — names stay untrusted text.
function nameNodes(name){
  const frag = document.createDocumentFragment();
  const parts = String(name).split("_");
  parts.forEach((seg, i) => {
    const last = i === parts.length - 1;
    frag.append(document.createTextNode(last ? seg : seg + "_"));
    if(!last) frag.append(document.createElement("wbr"));
  });
  return frag;
}

const needsAction = rec =>
  (rec.status || "active") === "active" && !(rec.next_action || "").trim();

let dragged = null;
function card(rec, from){
  const open = openCard === rec.name;
  const archived = ARCHIVED.has(rec.status);
  const d = document.createElement("div");
  d.className = "card" + (open ? " open" : "") + (archived ? " archived" : "")
              + (from === "board" && rec.rank === 1 ? " front" : "");
  d.dataset.name = rec.name;
  d.draggable = !open && !archived;

  const row = document.createElement("div"); row.className = "nm";
  // Rank is a live-lane position, so an archived card has none to show — its stored
  // rank is the placeholder the archive op parks it at, never a real standing.
  if(from !== "inbox" && !archived){
    const rk = document.createElement("span"); rk.className = "rk";
    rk.textContent = rec.rank ?? "—";
    row.append(rk);
  }
  const h = document.createElement("h3");
  h.append(nameNodes(rec.name));
  row.append(h);
  d.append(row);

  if(!open){
    const p = document.createElement("p");
    p.className = "purpose" + (rec.purpose ? "" : " none");
    p.textContent = rec.purpose || "No purpose yet";
    d.append(p);
  }
  // Family (2026-10-03 organization pass): a row either sits under a parent or heads one.
  if(from !== "inbox"){
    const kids = REG.projects.filter(k => k.parent === rec.name);
    const live = kids.filter(k => !ARCHIVED.has(k.status)).length;
    const text = rec.parent ? "↳ part of " + rec.parent
               : kids.length ? `family: ${live} live, ${kids.length - live} merged/retired` : "";
    if(text){
      const f = document.createElement("div"); f.className = "fam"; f.textContent = text;
      d.append(f);
    }
  }
  if(from !== "inbox"){
    const s = document.createElement("div"); s.className = "stage";
    const leds = document.createElement("div"); leds.className = "leds";
    const reached = idx(rec.stage);
    STAGES.forEach((_, i) => {
      const led = document.createElement("i");
      if(i <= reached) led.className = "on";
      leds.append(led);
    });
    const lab = document.createElement("b");
    lab.textContent = `${rec.stage || "unstaged"} ${reached+1}/${STAGES.length}`;
    s.append(leds, lab);

    // The pill rides the stage row, not the name row. Sharing a line with the title
    // cost it half its width and forced every name to two or three lines; the stage
    // row had the room to spare.
    const sel = document.createElement("select");
    const st = rec.status || "active";
    sel.className = "st st-" + st;
    STATUSES.forEach(v => {
      const o = document.createElement("option");
      o.value = v; o.textContent = v; o.selected = v === st;
      sel.append(o);
    });
    sel.onmousedown = e => e.stopPropagation();
    sel.onclick = e => e.stopPropagation();
    sel.onchange = e => {
      e.stopPropagation();
      write(`/api/project/${encodeURIComponent(rec.name)}`, {status: sel.value});
    };
    s.append(sel);
    d.append(s);

    // Promotion is gate-free, so the gap is surfaced here instead of blocking the
    // drag. Same predicate render.py uses — active only, whitespace counts as
    // blank — so the board and the dashboard cannot disagree about it.
    if(needsAction(rec)){
      const f = document.createElement("div"); f.className = "needs";
      f.textContent = "⚠ Needs a next action";
      d.append(f);
    }
  }
  if(open) d.append(panel(rec, from));

  d.onclick = () => { openCard = open ? null : rec.name; render(); };
  d.addEventListener("dragstart", e => {
    dragged = {rec, from};
    d.classList.add("dragging");
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", rec.name);
  });
  d.addEventListener("dragend", () => { dragged = null; d.classList.remove("dragging"); });
  return d;
}

function panel(rec, from){
  const p = document.createElement("div"); p.className = "panel";
  p.onclick = e => e.stopPropagation();
  p.onmousedown = e => e.stopPropagation();

  if(from === "inbox"){
    const w = document.createElement("div"); w.className = "note";
    w.textContent = "Drag onto a stage column to promote, or onto Archive to retire it. "
                  + "Neither needs anything filled in first — a promoted project just wears "
                  + "a red flag until it has a next action.";
    p.append(w);
  }
  // The board shows one lane at a time and drops into the lane it is showing, so a
  // mislabeled project can only be moved from here.
  if(from !== "inbox"){
    const l = document.createElement("label"); l.textContent = "lane";
    const g = document.createElement("div"); g.className = "lanes";
    LANES.forEach(v => {
      const b = document.createElement("button");
      b.className = "lanebtn" + (v === rec.lane ? " on" : "");
      b.textContent = v;
      b.disabled = v === rec.lane;
      b.onclick = async () => {
        if(await write(`/api/project/${encodeURIComponent(rec.name)}/lane`, {lane: v})){
          lane = v;          // follow the card to its new lane instead of losing it
          render();
        }
      };
      g.append(b);
    });
    p.append(l, g);
  }

  const field = (key, label, tag) => {
    const l = document.createElement("label"); l.textContent = label;
    const el = document.createElement(tag);
    if(tag === "textarea") el.rows = 3;
    el.value = rec[key] || "";
    if(!el.value) el.classList.add("missing");
    el.oninput = () => {
      rec[key] = el.value;
      el.classList.toggle("missing", !el.value);
      if(from === "inbox"){
        const d = drafts.get(rec.name) || {};
        d[key] = el.value;
        drafts.set(rec.name, d);
      }
    };
    el.onchange = () => {
      if(from === "inbox") return;             // inbox edits are held until promotion
      write(`/api/project/${encodeURIComponent(rec.name)}`, {[key]: el.value});
    };
    p.append(l, el);
  };
  field("purpose", "purpose", "textarea");
  field("next_action", "next action", "input");

  if(from !== "inbox"){
    const l = document.createElement("label"); l.textContent = "add update";
    const add = document.createElement("input");
    add.placeholder = "one line, then Enter";
    add.onkeydown = e => {
      if(e.key !== "Enter" || !add.value.trim()) return;
      write(`/api/project/${encodeURIComponent(rec.name)}`, {note: add.value.trim()});
    };
    p.append(l, add);
    (rec.updates || []).slice(0, 6).forEach(u => {
      const d = document.createElement("div"); d.className = "up";
      const b = document.createElement("b"); b.textContent = u.date + " ";
      d.append(b, document.createTextNode(u.note));
      p.append(d);
    });
    const del = document.createElement("button");
    del.className = "danger"; del.textContent = "Delete project";
    del.onclick = () => {
      if(confirm(`Delete "${rec.name}"? This rewrites portfolio.json.`))
        write(`/api/project/${encodeURIComponent(rec.name)}`, null, "DELETE");
    };
    p.append(del);
  }
  return p;
}

function column(title, count, cls){
  const c = document.createElement("div"); c.className = "col " + (cls || "");
  const h = document.createElement("h2");
  const a = document.createElement("span"); a.textContent = title;
  const b = document.createElement("span"); b.className = "n"; b.textContent = count;
  h.append(a, b);
  const z = document.createElement("div"); z.className = "drop";
  c.append(h, z);
  return {col: c, zone: z};
}

function emptyNote(zone, text){
  const e = document.createElement("p"); e.className = "empty"; e.textContent = text;
  zone.append(e);
}

function dropTarget(colEl, zoneEl, stage){
  colEl.addEventListener("dragover", e => { e.preventDefault(); colEl.classList.add("over"); });
  colEl.addEventListener("dragleave", () => colEl.classList.remove("over"));
  colEl.addEventListener("drop", e => {
    e.preventDefault(); colEl.classList.remove("over");
    if(!dragged) return;
    const cards = [...zoneEl.querySelectorAll(".card")].filter(c => c.dataset.name !== dragged.rec.name);
    let position = cards.length;
    for(let i = 0; i < cards.length; i++){
      const r = cards[i].getBoundingClientRect();
      if(e.clientY < r.top + r.height/2){ position = i; break; }
    }
    const {rec, from} = dragged;
    if(from === "inbox"){
      write(`/api/inbox/${encodeURIComponent(rec.name)}/promote`,
            {lane, stage, position, purpose: rec.purpose || "", next_action: rec.next_action || ""})
        .then(ok => { if(ok) drafts.delete(rec.name); });
    } else {
      write("/api/move", {name: rec.name, lane, stage, position});
    }
  });
}

// Archive is a drop target too, but it has no ordering: `position` is meaningless
// there, and /api/move would reject "archive" anyway — it is not a stage. So this
// is deliberately separate from dropTarget rather than a call with a fake stage.
function archiveTarget(colEl){
  colEl.addEventListener("dragover", e => { e.preventDefault(); colEl.classList.add("over"); });
  colEl.addEventListener("dragleave", () => colEl.classList.remove("over"));
  colEl.addEventListener("drop", e => {
    e.preventDefault(); colEl.classList.remove("over");
    if(!dragged) return;
    const {rec, from} = dragged;
    if(from === "inbox"){
      // an idea that never went anywhere: no purpose or next action required
      write(`/api/inbox/${encodeURIComponent(rec.name)}/archive`,
            {lane, purpose: rec.purpose || "", next_action: rec.next_action || ""})
        .then(ok => { if(ok) drafts.delete(rec.name); });
    } else {
      write(`/api/project/${encodeURIComponent(rec.name)}`, {status: "dropped"});
    }
  });
}

function render(){
  const app = document.getElementById("app");
  app.textContent = "";
  const wrap = document.createElement("div"); wrap.className = "cols";

  const inbox = REG.inbox || [];
  const ib = column("Inbox", inbox.length, "inbox");
  inbox.forEach(r => ib.zone.append(card(r, "inbox")));
  if(!inbox.length) emptyNote(ib.zone, "Nothing captured");
  wrap.append(ib.col);

  // Rows backfilled 2026-10-03 have no stage. Shown, not droppable: drag one onto a
  // stage column to give it a stage.
  const unstaged = live(lane).filter(p => !STAGES.includes(p.stage));
  if(unstaged.length){
    const u = column("unstaged", unstaged.length, "unstaged");
    unstaged.forEach(p => u.zone.append(card(p, "board")));
    wrap.append(u.col);
  }

  STAGES.forEach(s => {
    const list = live(lane).filter(p => p.stage === s);
    const c = column(s, list.length);
    list.forEach(p => c.zone.append(card(p, "board")));
    if(!list.length) emptyNote(c.zone, "Empty");
    dropTarget(c.col, c.zone, s);
    wrap.append(c.col);
  });

  const arch = REG.projects.filter(p => p.lane === lane && ARCHIVED.has(p.status));
  const ac = column("Archive", arch.length, "archive");
  arch.forEach(p => ac.zone.append(card(p, "board")));
  if(!arch.length) emptyNote(ac.zone, "Drop here to retire");
  archiveTarget(ac.col);
  wrap.append(ac.col);
  app.append(wrap);

  document.getElementById("meta").textContent =
    `${REG.projects.length} projects · ${inbox.length} inbox · ${arch.length} archived`;

  const tabs = document.getElementById("tabs");
  tabs.textContent = "";
  LANES.forEach(l => {
    const b = document.createElement("button");
    b.className = "tab" + (l === lane ? " on" : "");
    b.textContent = l;
    b.onclick = () => { lane = l; openCard = null; render(); };
    tabs.append(b);
  });
}

document.getElementById("undo").onclick = () => write("/api/undo", {});
