  :root{
    --field-black:#0a0d0b; --bug-panel:#111613; --bug-edge:#1e2620;
    --baylor-green:#154734; --deep-turf:#0f3626; --green-line:#205540;
    --gold:#ffb81c; --deep-gold:#cf9410; --ink-on-gold:#171207;
    --chalk:#f4f6f3; --sideline-mist:#bad2c6; --faint-mist:#84a394;
    --flag-red:#ff5147; --track:#0c2118;
    --display:'Oswald','Arial Narrow',ui-sans-serif,system-ui,sans-serif;
    --prose:ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;
  }
  /* No light theme, by decision — a broadcast graphic doesn't get one. */
  html{color-scheme:dark}
  *{box-sizing:border-box}
  body{margin:0;background:var(--field-black);color:var(--chalk);
       font:13px/1.5 var(--prose)}

  /* ---------- masthead ---------- */
  header{display:flex;gap:14px;align-items:center;padding:13px 18px;
         background:var(--bug-panel);border-bottom:1px solid var(--bug-edge)}
  h1{margin:0;font:700 21px/1 var(--display);letter-spacing:.09em;text-transform:uppercase}
  h1 em{font-style:normal;color:var(--gold)}
  #meta{font:700 11px/1 var(--display);letter-spacing:.1em;text-transform:uppercase;
        color:var(--faint-mist);font-variant-numeric:tabular-nums}
  .tabs{display:flex;gap:6px;margin-left:auto}
  .tab,button.plain{font:700 11.5px/1 var(--display);letter-spacing:.12em;
        text-transform:uppercase;cursor:pointer;border-radius:3px;padding:7px 15px;
        background:transparent;color:var(--sideline-mist);
        border:1px solid var(--green-line);transition:color .16s,border-color .16s}
  .tab:hover,button.plain:hover{color:var(--chalk);border-color:var(--sideline-mist)}
  .tab.on{background:var(--gold);border-color:var(--gold);color:var(--ink-on-gold)}
  .tab.on:hover{color:var(--ink-on-gold)}
  :focus-visible{outline:2px solid var(--gold);outline-offset:2px}

  /* ---------- the turf ---------- */
  /* Baylor green is one continuous field under every column, not eight saturated
     blocks — that keeps the 30-60% green commitment while the black cards stay the
     things you actually read. */
  .cols{display:flex;padding:0;overflow-x:auto;align-items:stretch;
        background:var(--baylor-green);min-height:calc(100vh - 51px)}
  .col{min-width:252px;width:252px;flex:0 0 auto;
       border-right:1px solid var(--green-line);display:flex;flex-direction:column}
  .col>h2{margin:0;padding:11px 13px;display:flex;justify-content:space-between;
          gap:8px;align-items:baseline;background:var(--deep-turf);
          border-bottom:2px solid var(--gold);
          font:700 12px/1 var(--display);letter-spacing:.14em;text-transform:uppercase;
          color:var(--chalk)}
  .col>h2 .n{color:var(--gold);font-variant-numeric:tabular-nums;letter-spacing:.06em}
  .drop{padding:11px;display:flex;flex-direction:column;gap:9px;flex:1;
        transition:background .16s}
  .col.over .drop{background:#1c5a43}
  .col.over>h2{border-bottom-color:var(--chalk)}
  /* the inbox and the archive are not stages: mark them by surface, not by hue */
  .col.inbox{background:var(--bug-panel);border-right:1px solid var(--bug-edge)}
  .col.inbox>h2{background:#0d120f;border-bottom-color:var(--sideline-mist)}
  .col.inbox>h2 .n{color:var(--sideline-mist)}
  .col.archive{background:#0d1b15}
  .col.archive>h2{background:#0b1712;border-bottom-color:var(--green-line)}
  .col.archive>h2 .n{color:var(--faint-mist)}
  .empty{font:400 12px/1.4 var(--prose);color:var(--faint-mist);opacity:.6;
         padding:3px 2px;font-style:italic}

  /* ---------- cards ---------- */
  .card{background:var(--bug-panel);border:1px solid var(--bug-edge);border-radius:8px;
        padding:10px 11px;cursor:grab;position:relative;overflow:hidden;
        box-shadow:0 2px 0 rgba(0,0,0,.45),0 14px 30px -22px rgba(0,0,0,.8);
        transition:border-color .16s,transform .16s}
  .card:hover{border-color:var(--green-line);transform:translateY(-1px)}
  .card.open{cursor:default;transform:none;border-color:var(--green-line)}
  .card.dragging{opacity:.4}
  /* The gold left bar is the system's signature mark, so it stays rare: only the
     #1 card in the lane gets it. On every card it would be wallpaper, and gold
     would stop meaning "this is the one." */
  .card.front::before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;
        background:var(--gold)}
  .card.front{padding-left:15px}

  .nm{display:flex;gap:9px;align-items:flex-start}
  .rk{font:700 17px/1 var(--display);color:var(--gold);font-variant-numeric:tabular-nums;
      letter-spacing:.02em;flex:0 0 auto;min-width:15px;padding-top:1px}
  .card.archived .rk{color:var(--faint-mist)}
  h3{margin:0;flex:1;min-width:0;font:700 14px/1.25 var(--display);letter-spacing:.045em;
     text-transform:uppercase;color:var(--chalk);
     /* names are one unbroken word joined by underscores; <wbr> marks the joins so a
        break lands there instead of mid-syllable. break-word is the last resort for a
        single segment longer than the column. */
     overflow-wrap:break-word}
  .card.archived h3{color:var(--sideline-mist)}
  .purpose{margin:7px 0 0;font:400 12.5px/1.45 var(--prose);color:var(--sideline-mist);
        display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
  .purpose.none{color:var(--faint-mist);font-style:italic;opacity:.75}

  /* status pill — native select, system colors. The four DESIGN.md variants. */
  select.st{flex:0 0 auto;appearance:none;-webkit-appearance:none;
        font:700 10.5px/1 var(--display);letter-spacing:.09em;text-transform:uppercase;
        padding:3px 7px;border-radius:3px;cursor:pointer;
        background:transparent;color:var(--sideline-mist);
        border:none;box-shadow:inset 0 0 0 1px var(--green-line);
        transition:box-shadow .16s}
  select.st option{background:var(--bug-panel);color:var(--chalk);font-family:var(--prose)}
  select.st-active{background:var(--gold);color:var(--ink-on-gold);box-shadow:none}
  select.st-paused{color:var(--sideline-mist);box-shadow:inset 0 0 0 1px var(--sideline-mist)}
  select.st-dropped{color:var(--flag-red);box-shadow:inset 0 0 0 1px var(--flag-red)}
  select.st-done{background:var(--deep-turf);color:var(--sideline-mist);
        box-shadow:inset 0 0 0 1px var(--green-line)}

  /* stage readout — the LED strip, the system's second signature geometry */
  .stage{display:flex;gap:7px;align-items:center;margin-top:9px}
  .stage select.st{margin-left:auto}
  .leds{display:flex;gap:2px;flex:0 0 auto}
  .leds i{display:block;width:11px;height:6px;border-radius:2px;background:var(--track);
        box-shadow:inset 0 0 0 1px rgba(255,255,255,.07);
        transition:background .22s cubic-bezier(.22,1,.36,1)}
  .leds i.on{background:linear-gradient(180deg,var(--gold),var(--deep-gold));box-shadow:none}
  .card.archived .leds i.on{background:var(--green-line)}
  .stage b{font:700 10.5px/1 var(--display);letter-spacing:.08em;text-transform:uppercase;
        color:var(--faint-mist);font-variant-numeric:tabular-nums;white-space:nowrap}

  /* ---------- editing panel ---------- */
  .panel{margin-top:10px;padding-top:10px;border-top:1px solid var(--bug-edge);
         display:flex;flex-direction:column;gap:7px}
  .panel label{font:700 10.5px/1 var(--display);letter-spacing:.12em;text-transform:uppercase;
         color:var(--faint-mist)}
  .panel textarea,.panel input{width:100%;max-width:100%;background:var(--field-black);
        color:var(--chalk);border:1px solid var(--green-line);border-radius:6px;
        padding:7px 8px;font-family:var(--prose);font-size:12.5px;line-height:1.45;
        transition:border-color .16s}
  .panel textarea{resize:vertical;min-height:58px}
  .panel textarea:focus,.panel input:focus{border-color:var(--sideline-mist)}
  .panel .missing{border-color:#5c2a26}
  .up{font:400 11.5px/1.45 var(--prose);color:var(--sideline-mist);
      background:var(--field-black);border-radius:4px;padding:6px 8px}
  .up b{color:var(--faint-mist);font-weight:500;font-variant-numeric:tabular-nums}
  .warn{font:400 11.5px/1.45 var(--prose);color:var(--flag-red);background:#26100f;
        border:1px solid #5c2a26;border-radius:6px;padding:7px 8px}
  /* guidance, not an alarm — nothing is blocked, so it does not get Flag Red */
  .note{font:400 11.5px/1.45 var(--prose);color:var(--faint-mist);
        background:var(--field-black);border-radius:6px;padding:7px 8px}
  .fam{margin-top:6px;font:600 11px/1.3 var(--prose);color:var(--faint-mist)}
  .needs{margin-top:8px;font:700 10.5px/1.3 var(--display);letter-spacing:.07em;
        text-transform:uppercase;color:var(--flag-red)}
  .lanes{display:flex;gap:5px}
  .lanebtn{flex:1;font:700 10.5px/1 var(--display);letter-spacing:.12em;text-transform:uppercase;
        background:transparent;color:var(--sideline-mist);border:1px solid var(--green-line);
        border-radius:3px;padding:7px 9px;cursor:pointer;
        transition:color .16s,border-color .16s}
  .lanebtn:hover:not(:disabled){color:var(--chalk);border-color:var(--sideline-mist)}
  .lanebtn.on{background:var(--gold);border-color:var(--gold);color:var(--ink-on-gold);
        cursor:default}
  button.danger{font:700 10.5px/1 var(--display);letter-spacing:.12em;text-transform:uppercase;
        background:transparent;color:var(--faint-mist);border:1px solid var(--green-line);
        border-radius:3px;padding:7px 10px;cursor:pointer;margin-top:2px;
        transition:color .16s,border-color .16s}
  button.danger:hover{color:var(--flag-red);border-color:var(--flag-red)}

  .flash{position:fixed;bottom:18px;left:50%;transform:translateX(-50%);z-index:99;
         background:#26100f;color:var(--flag-red);border:1px solid #5c2a26;
         padding:9px 15px;border-radius:6px;font:400 12.5px/1.4 var(--prose);
         display:none;max-width:70vw;box-shadow:0 12px 30px -12px rgba(0,0,0,.9)}
  .blocked{padding:26px;color:var(--flag-red);font:400 13px/1.5 var(--prose)}

  @media (prefers-reduced-motion:reduce){*{transition:none!important}}
</style>
</head>
<body>
<header>
  <h1>Portfolio <em>Board</em></h1>
  <span id="meta"></span>
  <div class="tabs" id="tabs"></div>
  <button class="plain" id="undo">Undo</button>
</header>
<div id="app"></div>
<div class="flash" id="flash"></div>

<script>
const TOKEN = new URLSearchParams(location.search).get("token") || "";
const STAGES = ["idea","grilled","spec","planned","building","shipped"];
const STATUSES = ["active","paused","done","dropped","merged","archived"];
const ARCHIVED = new Set(["done","dropped","merged","archived"]);
// Mirrors portfolio.LANES. job counts against the slate cap; side is personal work.
const LANES = ["job","side","system","knowledge","tool"];
let REG = null, lane = "job", openCard = null;
const drafts = new Map();          // inbox name -> {purpose?, next_action?} draft edits not yet promoted

function applyDrafts(){
  (REG.inbox || []).forEach(r => {
    const d = drafts.get(r.name);
    if(d) Object.assign(r, d);
  });
}

function flash(msg){
  const f = document.getElementById("flash");
  f.textContent = msg; f.style.display = "block";
  clearTimeout(flash.t); flash.t = setTimeout(()=>f.style.display="none", 5000);
}
async function api(path, opts = {}){
  const sep = path.includes("?") ? "&" : "?";
  const res = await fetch(path + sep + "token=" + encodeURIComponent(TOKEN), {
    headers: {"Content-Type":"application/json"}, ...opts
  });
  if(!res.ok){
    let msg = res.statusText;
    try { msg = (await res.json()).error || msg; } catch {}
    throw new Error(msg);
  }
  return res.json();
}
function showBlocked(msg){
  const app = document.getElementById("app");
  app.textContent = "";
  const p = document.createElement("p");
  p.className = "blocked";
  p.textContent = "Cannot load the board: " + msg;
  app.append(p);
}
async function load(){
  try {
    REG = await api("/api/registry");
    applyDrafts();
    render();
  } catch(e){
    flash(e.message);
    if(!REG) showBlocked(e.message);
  }
}

// any failed write reloads from disk, so the board never shows a state that was not saved
async function write(path, payload, method = "POST"){
  let ok = true;
  try {
    const opts = {method};
    if(method !== "DELETE") opts.body = JSON.stringify(payload || {});
    await api(path, opts);
  } catch(e){
    ok = false;
    flash(e.message);
  }
  await load();          // load() handles its own errors, so a failed reload is never silent
  return ok;
}

const idx = s => Math.max(0, STAGES.indexOf(s));
const live = l => REG.projects
  .filter(p => p.lane === l && !ARCHIVED.has(p.status))
  .sort((a,b) => (a.rank||1e6) - (b.rank||1e6));

// Project names are one long word joined by underscores, so the browser has no break
// opportunity and cuts mid-syllable ("AT_Utilization_B / enchmarks"). Mark the joins
// with <wbr> instead. Built as nodes, not innerHTML — names stay untrusted text.
function nameNodes(name){
  const frag = document.createDocumentFragment();
  const parts = String(name).split("_");
  parts.forEach((seg, i) => {
    const last = i === parts.length - 1;
    frag.append(document.createTextNode(last ? seg : seg + "_"));
    if(!last) frag.append(document.createElement("wbr"));
  });
  return frag;
}

const needsAction = rec =>
  (rec.status || "active") === "active" && !(rec.next_action || "").trim();

let dragged = null;
function card(rec, from){
  const open = openCard === rec.name;
  const archived = ARCHIVED.has(rec.status);
  const d = document.createElement("div");
  d.className = "card" + (open ? " open" : "") + (archived ? " archived" : "")
              + (from === "board" && rec.rank === 1 ? " front" : "");
  d.dataset.name = rec.name;
  d.draggable = !open && !archived;

  const row = document.createElement("div"); row.className = "nm";
  // Rank is a live-lane position, so an archived card has none to show — its stored
  // rank is the placeholder the archive op parks it at, never a real standing.
  if(from !== "inbox" && !archived){
    const rk = document.createElement("span"); rk.className = "rk";
    rk.textContent = rec.rank ?? "—";
    row.append(rk);
  }
  const h = document.createElement("h3");
  h.append(nameNodes(rec.name));
  row.append(h);
  d.append(row);

  if(!open){
    const p = document.createElement("p");
    p.className = "purpose" + (rec.purpose ? "" : " none");
    p.textContent = rec.purpose || "No purpose yet";
    d.append(p);
  }
  // Family (2026-10-03 organization pass): a row either sits under a parent or heads one.
  if(from !== "inbox"){
    const kids = REG.projects.filter(k => k.parent === rec.name);
    const live = kids.filter(k => !ARCHIVED.has(k.status)).length;
    const text = rec.parent ? "↳ part of " + rec.parent
               : kids.length ? `family: ${live} live, ${kids.length - live} merged/retired` : "";
    if(text){
      const f = document.createElement("div"); f.className = "fam"; f.textContent = text;
      d.append(f);
    }
  }
  if(from !== "inbox"){
    const s = document.createElement("div"); s.className = "stage";
    const leds = document.createElement("div"); leds.className = "leds";
    const reached = idx(rec.stage);
    STAGES.forEach((_, i) => {
      const led = document.createElement("i");
      if(i <= reached) led.className = "on";
      leds.append(led);
    });
    const lab = document.createElement("b");
    lab.textContent = `${rec.stage || "unstaged"} ${reached+1}/${STAGES.length}`;
    s.append(leds, lab);

    // The pill rides the stage row, not the name row. Sharing a line with the title
    // cost it half its width and forced every name to two or three lines; the stage
    // row had the room to spare.
    const sel = document.createElement("select");
    const st = rec.status || "active";
    sel.className = "st st-" + st;
    STATUSES.forEach(v => {
      const o = document.createElement("option");
      o.value = v; o.textContent = v; o.selected = v === st;
      sel.append(o);
    });
    sel.onmousedown = e => e.stopPropagation();
    sel.onclick = e => e.stopPropagation();
    sel.onchange = e => {
      e.stopPropagation();
      write(`/api/project/${encodeURIComponent(rec.name)}`, {status: sel.value});
    };
    s.append(sel);
    d.append(s);

    // Promotion is gate-free, so the gap is surfaced here instead of blocking the
    // drag. Same predicate render.py uses — active only, whitespace counts as
    // blank — so the board and the dashboard cannot disagree about it.
    if(needsAction(rec)){
      const f = document.createElement("div"); f.className = "needs";
      f.textContent = "⚠ Needs a next action";
      d.append(f);
    }
  }
  if(open) d.append(panel(rec, from));

  d.onclick = () => { openCard = open ? null : rec.name; render(); };
  d.addEventListener("dragstart", e => {
    dragged = {rec, from};
    d.classList.add("dragging");
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", rec.name);
  });
  d.addEventListener("dragend", () => { dragged = null; d.classList.remove("dragging"); });
  return d;
}

function panel(rec, from){
  const p = document.createElement("div"); p.className = "panel";
  p.onclick = e => e.stopPropagation();
  p.onmousedown = e => e.stopPropagation();

  if(from === "inbox"){
    const w = document.createElement("div"); w.className = "note";
    w.textContent = "Drag onto a stage column to promote, or onto Archive to retire it. "
                  + "Neither needs anything filled in first — a promoted project just wears "
                  + "a red flag until it has a next action.";
    p.append(w);
  }
  // The board shows one lane at a time and drops into the lane it is showing, so a
  // mislabeled project can only be moved from here.
  if(from !== "inbox"){
    const l = document.createElement("label"); l.textContent = "lane";
    const g = document.createElement("div"); g.className = "lanes";
    LANES.forEach(v => {
      const b = document.createElement("button");
      b.className = "lanebtn" + (v === rec.lane ? " on" : "");
      b.textContent = v;
      b.disabled = v === rec.lane;
      b.onclick = async () => {
        if(await write(`/api/project/${encodeURIComponent(rec.name)}/lane`, {lane: v})){
          lane = v;          // follow the card to its new lane instead of losing it
          render();
        }
      };
      g.append(b);
    });
    p.append(l, g);
  }

  const field = (key, label, tag) => {
    const l = document.createElement("label"); l.textContent = label;
    const el = document.createElement(tag);
    if(tag === "textarea") el.rows = 3;
    el.value = rec[key] || "";
    if(!el.value) el.classList.add("missing");
    el.oninput = () => {
      rec[key] = el.value;
      el.classList.toggle("missing", !el.value);
      if(from === "inbox"){
        const d = drafts.get(rec.name) || {};
        d[key] = el.value;
        drafts.set(rec.name, d);
      }
    };
    el.onchange = () => {
      if(from === "inbox") return;             // inbox edits are held until promotion
      write(`/api/project/${encodeURIComponent(rec.name)}`, {[key]: el.value});
    };
    p.append(l, el);
  };
  field("purpose", "purpose", "textarea");
  field("next_action", "next action", "input");

  if(from !== "inbox"){
    const l = document.createElement("label"); l.textContent = "add update";
    const add = document.createElement("input");
    add.placeholder = "one line, then Enter";
    add.onkeydown = e => {
      if(e.key !== "Enter" || !add.value.trim()) return;
      write(`/api/project/${encodeURIComponent(rec.name)}`, {note: add.value.trim()});
    };
    p.append(l, add);
    (rec.updates || []).slice(0, 6).forEach(u => {
      const d = document.createElement("div"); d.className = "up";
      const b = document.createElement("b"); b.textContent = u.date + " ";
      d.append(b, document.createTextNode(u.note));
      p.append(d);
    });
    const del = document.createElement("button");
    del.className = "danger"; del.textContent = "Delete project";
    del.onclick = () => {
      if(confirm(`Delete "${rec.name}"? This rewrites portfolio.json.`))
        write(`/api/project/${encodeURIComponent(rec.name)}`, null, "DELETE");
    };
    p.append(del);
  }
  return p;
}

function column(title, count, cls){
  const c = document.createElement("div"); c.className = "col " + (cls || "");
  const h = document.createElement("h2");
  const a = document.createElement("span"); a.textContent = title;
  const b = document.createElement("span"); b.className = "n"; b.textContent = count;
  h.append(a, b);
  const z = document.createElement("div"); z.className = "drop";
  c.append(h, z);
  return {col: c, zone: z};
}

function emptyNote(zone, text){
  const e = document.createElement("p"); e.className = "empty"; e.textContent = text;
  zone.append(e);
}

function dropTarget(colEl, zoneEl, stage){
  colEl.addEventListener("dragover", e => { e.preventDefault(); colEl.classList.add("over"); });
  colEl.addEventListener("dragleave", () => colEl.classList.remove("over"));
  colEl.addEventListener("drop", e => {
    e.preventDefault(); colEl.classList.remove("over");
    if(!dragged) return;
    const cards = [...zoneEl.querySelectorAll(".card")].filter(c => c.dataset.name !== dragged.rec.name);
    let position = cards.length;
    for(let i = 0; i < cards.length; i++){
      const r = cards[i].getBoundingClientRect();
      if(e.clientY < r.top + r.height/2){ position = i; break; }
    }
    const {rec, from} = dragged;
    if(from === "inbox"){
      write(`/api/inbox/${encodeURIComponent(rec.name)}/promote`,
            {lane, stage, position, purpose: rec.purpose || "", next_action: rec.next_action || ""})
        .then(ok => { if(ok) drafts.delete(rec.name); });
    } else {
      write("/api/move", {name: rec.name, lane, stage, position});
    }
  });
}

// Archive is a drop target too, but it has no ordering: `position` is meaningless
// there, and /api/move would reject "archive" anyway — it is not a stage. So this
// is deliberately separate from dropTarget rather than a call with a fake stage.
function archiveTarget(colEl){
  colEl.addEventListener("dragover", e => { e.preventDefault(); colEl.classList.add("over"); });
  colEl.addEventListener("dragleave", () => colEl.classList.remove("over"));
  colEl.addEventListener("drop", e => {
    e.preventDefault(); colEl.classList.remove("over");
    if(!dragged) return;
    const {rec, from} = dragged;
    if(from === "inbox"){
      // an idea that never went anywhere: no purpose or next action required
      write(`/api/inbox/${encodeURIComponent(rec.name)}/archive`,
            {lane, purpose: rec.purpose || "", next_action: rec.next_action || ""})
