"""Where files landed: a ledger of files created or changed, mapped to registry projects.

Built from the file systems themselves (git in every DEV repo, file times on the Drive
primary storage and the vault), not from Claude's tool calls, so a file written by a
script or a shell copy is in it too. Decided 2026-10-03 (Eric).

    python landed.py scan [--days 2]        # ~1-2 min, mostly the Drive walk; run in the background
    python landed.py show [--days 1] [--project X] [--json]

The ledger is one JSONL per machine in ~/.claude/global-memory/landed/ (synced by git;
one file per machine so the two never conflict), 30 days kept. `show` merges both.
Each path is mapped to its project through the registry's dev_folder and drive_folder.
Paths that look like athlete or health records are left out entirely, since the ledger
is pushed to GitHub (same patterns as Flint's catalog exclusions).
"""

from __future__ import annotations

import argparse
import datetime as _dt
import json
import os
import platform
import re
import subprocess
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
DEV = HERE.parent
HOME = Path.home()
KEEP_DAYS = 30
LEDGER_DIR = HOME / ".claude" / "global-memory" / "landed"
SENSITIVE = re.compile(
    r"(?i)DEXA[_ ]?Project|athlete-snapshots|pff-snapshots|Injur(y|ies)|/Roster/|roster[^/]*\.(xlsx?|csv)$"
    r"|/Personnel(_Interview_Docs)?/|WBB_athletes|Athlete_Performance_Overview|Spirit Squad|ICE ?Form|/\.git/")
SKIP_DIRS = {".git", "node_modules", ".venv", "venv", "__pycache__", "renv", ".Rproj.user", ".claude",
             ".obsidian", ".trash"}


        except OSError:
            continue
    return out


def entry(root: str, rel: str, when: str, how: str) -> dict:
    return {"root": root, "path": rel, "when": when, "how": how, "machine": platform.node()}


# ---- projects ----------------------------------------------------------------

def project_index(registry: dict) -> list[tuple[str, str, str]]:
    """(root, prefix, project) sorted longest prefix first, so the most specific row wins."""
    idx = []
    for p in registry.get("projects", []):
        if p.get("dev_folder"):
            idx.append(("DEV", p["dev_folder"].replace("\\", "/").rstrip("/") + "/", p["name"]))
        if p.get("drive_folder"):
            idx.append(("DRIVE", p["drive_folder"].replace("\\", "/").rstrip("/") + "/", p["name"]))
    return sorted(idx, key=lambda t: -len(t[1]))


def project_for(e: dict, idx: list[tuple[str, str, str]]) -> str:
    for root, prefix, name in idx:
        if e["root"] == root and e["path"].startswith(prefix):
            return name
    head = e["path"].split("/", 1)[0]
    return {"DEV": f"(DEV) {head}", "DRIVE": f"(Drive) {head}", "VAULT": "(vault)"}.get(e["root"], head)


def keep(e: dict) -> bool:
    return not SENSITIVE.search("/" + e["path"])


# ---- ledger ------------------------------------------------------------------

def merge(old: list[dict], new: list[dict], now: _dt.datetime) -> list[dict]:
    """Latest entry per (root, path); entries older than KEEP_DAYS dropped; newest first."""
    cutoff = (now - _dt.timedelta(days=KEEP_DAYS)).isoformat()
    best: dict[tuple[str, str], dict] = {}
    for e in [*old, *new]:
        if e["when"] < cutoff:
            continue
        key = (e["root"], e["path"])
        if key not in best or e["when"] >= best[key]["when"]:
            if key in best and best[key]["how"].startswith("new") and not e["how"].startswith("new"):
                e = {**e, "how": "new"}  # a file first seen as new stays new
            best[key] = e
    return sorted(best.values(), key=lambda e: e["when"], reverse=True)


def ledger_path() -> Path:
    return LEDGER_DIR / f"{platform.node()}.jsonl"


def read_ledgers() -> list[dict]:
    rows = []
    for f in sorted(LEDGER_DIR.glob("*.jsonl")):
        for line in f.read_text(encoding="utf-8").splitlines():
            if line.strip():
                rows.append(json.loads(line))
    return rows


def scan(days: float) -> int:
    now = _dt.datetime.now().astimezone()
    since = now - _dt.timedelta(days=days)
    found = scan_dev(since)
    for name, root in roots().items():
        if name != "DEV":
            found += scan_tree(name, root, since)
    found = [e for e in found if keep(e)]
    path = ledger_path()
    old = [json.loads(l) for l in path.read_text(encoding="utf-8").splitlines() if l.strip()] if path.exists() else []
    merged = merge(old, found, now)
    LEDGER_DIR.mkdir(parents=True, exist_ok=True)
    path.write_text("".join(json.dumps(e) + "\n" for e in merged), encoding="utf-8")
    print(f"landed: {len(found)} files in the last {days:g} day(s); ledger {len(merged)} entries -> {path}")
    return 0


def show(days: float, project: str | None, as_json: bool) -> int:
    sys.path.insert(0, str(HERE))
    import portfolio
    idx = project_index(portfolio.load_registry(HERE / "portfolio.json"))
    now = _dt.datetime.now().astimezone()
    cutoff = (now - _dt.timedelta(days=days)).isoformat()
    rows = [e for e in read_ledgers() if e["when"] >= cutoff]
    for e in rows:
        e["project"] = project_for(e, idx)
    if project:
        rows = [e for e in rows if project.lower() in e["project"].lower() or project.lower() in e["path"].lower()]
    if as_json:
        print(json.dumps(rows, indent=2))
        return 0
    newest = max((f.stat().st_mtime for f in LEDGER_DIR.glob("*.jsonl")), default=None)
    asof = _dt.datetime.fromtimestamp(newest).strftime("%a %H:%M") if newest else "never"
    groups: dict[str, list[dict]] = {}
    for e in sorted(rows, key=lambda e: e["when"], reverse=True):
        groups.setdefault(e["project"], []).append(e)
    print(f"Where files landed, last {days:g} day(s): {len(rows)} files in {len(groups)} places (ledger as of {asof})")
    base = roots()
    for name, items in sorted(groups.items(), key=lambda kv: kv[1][0]["when"], reverse=True):
        print(f"\n{name} ({len(items)})")
        for e in items[:12]:
            root = base.get(e["root"])
            full = (root / e["path"]) if root else Path(e["root"]) / e["path"]
            print(f"  {e['when'][5:16].replace('T', ' ')}  {e['how']:<20} {full}")
        if len(items) > 12:
            print(f"  ... {len(items) - 12} more (landed.py show --project \"{name}\")")
    return 0


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    sub = ap.add_subparsers(dest="cmd", required=True)
