// "3d ago" from an ISO timestamp; the machine goes in the tooltip.
function ago(iso){
  const days = Math.floor((Date.now() - new Date(iso).getTime()) / 864e5);
  return days <= 0 ? "today" : days === 1 ? "yesterday" : `${days}d ago`;
}

// The three resume lines (design: Resume card). Purpose is the fourth, shown above.
function resume(rc){
  const dl = document.createElement("dl"); dl.className = "resume";
  const line = (label, text, date, title) => {
    const dt = document.createElement("dt"); dt.textContent = label;
    const dd = document.createElement("dd");
    if(!text){ dd.className = "none"; dd.textContent = "nothing on record"; }
    else {
      if(date){
        const s = document.createElement("span"); s.className = "d"; s.textContent = date + " ";
        dd.append(s);
      }
      dd.append(document.createTextNode(text));
    }
    if(title) dd.title = title;
    dl.append(dt, dd);
  };
  line("stands", rc.stands, rc.stands_date ? rc.stands_date.slice(5) : "");
  line("next", rc.next, "", rc.next_from === "registry" ? "from the registry (no STATUS Next item)" : "");
  line("touched", rc.touched ? ago(rc.touched) : "", "",
       rc.touched ? `${rc.touched.slice(0, 16).replace("T", " ")} on ${rc.touched_on || "?"}` : "");
  return dl;
}

