577	  app.textContent = "";
578	  const wrap = document.createElement("div"); wrap.className = "cols";
579	
580	  const inbox = REG.inbox || [];
581	  const ib = column("Inbox", inbox.length, "inbox");
582	  inbox.forEach(r => ib.zone.append(card(r, "inbox")));
583	  if(!inbox.length) emptyNote(ib.zone, "Nothing captured");
584	  wrap.append(ib.col);
585	
586	  // Rows backfilled 2026-10-03 have no stage. Shown, not droppable: drag one onto a
587	  // stage column to give it a stage.
588	  const unstaged = live(lane).filter(p => !STAGES.includes(p.stage));
589	  if(unstaged.length){
590	    const u = column("unstaged", unstaged.length, "unstaged");
591	    unstaged.forEach(p => u.zone.append(card(p, "board")));
592	    wrap.append(u.col);
593	  }
594	
595	  STAGES.forEach(s => {
596	    const list = live(lane).filter(p => p.stage === s);
597	    const c = column(s, list.length);
598	    list.forEach(p => c.zone.append(card(p, "board")));
599	    if(!list.length) emptyNote(c.zone, "Empty");
600	    dropTarget(c.col, c.zone, s);
601	    wrap.append(c.col);
602	  });
