function render(){
  const app = document.getElementById("app");
  app.textContent = "";
  const wrap = document.createElement("div"); wrap.className = "cols";

  const inbox = REG.inbox || [];
  const ib = column("Inbox", inbox.length, "inbox");
  inbox.forEach(r => ib.zone.append(card(r, "inbox")));
  if(!inbox.length) emptyNote(ib.zone, "Nothing captured");
  wrap.append(ib.col);

  // Rows backfilled 2026-10-03 have no stage. Shown, not droppable: drag one onto a
  // stage column to give it a stage.
  const unstaged = live(lane).filter(p => !STAGES.includes(p.stage));
  if(unstaged.length){
    const u = column("unstaged", unstaged.length, "unstaged");
    unstaged.forEach(p => u.zone.append(card(p, "board")));
    wrap.append(u.col);
  }

  STAGES.forEach(s => {
    const list = live(lane).filter(p => p.stage === s);
    const c = column(s, list.length);
    list.forEach(p => c.zone.append(card(p, "board")));
    if(!list.length) emptyNote(c.zone, "Empty");
    dropTarget(c.col, c.zone, s);
    wrap.append(c.col);
  });

  const arch = REG.projects.filter(p => p.lane === lane && ARCHIVED.has(p.status));
  const ac = column("Archive", arch.length, "archive");
  arch.forEach(p => ac.zone.append(card(p, "board")));
  if(!arch.length) emptyNote(ac.zone, "Drop here to retire");
  archiveTarget(ac.col);
  wrap.append(ac.col);
  app.append(wrap);

  document.getElementById("meta").textContent =
    `${REG.projects.length} projects · ${inbox.length} inbox · ${arch.length} archived`;

  const tabs = document.getElementById("tabs");
  tabs.textContent = "";
  LANES.forEach(l => {
    const b = document.createElement("button");
    b.className = "tab" + (l === lane ? " on" : "");
    b.textContent = l;
    b.onclick = () => { lane = l; openCard = null; render(); };
    tabs.append(b);
  });
}

document.getElementById("undo").onclick = () => write("/api/undo", {});

// ---------- live polling: terminal edits reach the page ----------

