try { view = localStorage.getItem("board.view") || "focus"; } catch {}
const FOCUS_DAYS = 14;
function daysFrom(today, iso){
  return Math.round((new Date(iso.slice(0, 10)) - new Date(today)) / 864e5);
}
function inFocus(p){
  if((p.status || "active") === "active") return true;
  const c = REG.cards && REG.cards[p.name];
  if(!c) return false;
  if(p.status === "paused" && c.touched && -daysFrom(REG.today, c.touched) <= FOCUS_DAYS) return true;
  if(c.due){                          // a hard date coming up; overdue ones on paused rows stay hidden
    const d = daysFrom(REG.today, c.due);
    if(d >= 0 && d <= FOCUS_DAYS) return true;
  }
  return false;
}
function inView(p){
  if(query){
    const c = (REG.cards && REG.cards[p.name]) || {};
    return [p.name, p.purpose, p.next_action, c.next, c.stands, p.dev_folder, p.drive_folder]
      .some(v => (v || "").toLowerCase().includes(query));
  }
  return view === "all" || inFocus(p);
}
document.getElementById("q").addEventListener("input", e => {
  query = e.target.value.trim().toLowerCase(); if(REG) render();
});
document.getElementById("view").onclick = () => {
  view = view === "focus" ? "all" : "focus";
  try { localStorage.setItem("board.view", view); } catch {}
  render();
};

