"""Resume cards: what the live board needs to pick a project back up.

Design: docs/project-management-system-design.md, "Resume card". Four lines per
project, all read from files that already exist:

  what it is       registry `purpose`
  where it stands  newest dated STATUS entry, else the newest registry update
  next step        first item under STATUS `## Next`, else the registry `next_action`
  last touched     newest landed-ledger entry for the project, either machine

STATUS files differ: 60 have `## Done`, 87 keep progress under `## Current state`, a
few use dated headings. So "where it stands" is the newest dated entry in any section
except Next, Open questions and Gotchas (those hold plans and traps, not progress).
"""
from __future__ import annotations

import datetime as _dt
import re
from pathlib import Path

import landed
from board_ops import ARCHIVED

CLIP = 160
NOT_PROGRESS = ("next", "open question", "gotcha")
# a dated entry: optional bullet / number / heading marker, optional bold, then the date
DATED = re.compile(r"^\s*(?:(?:[-*+]|\d+\.|#{2,6})\s+)?(?:\*\*|__)?\s*(\d{4}-\d{2}-\d{2})\b(.*)$")
BULLET = re.compile(r"^\s*(?:[-*+]|\d+\.)\s*")


def _clean(text: str) -> str:
    text = re.sub(r"\*\*|__|`", "", text).strip().lstrip(":–—- ").strip()
    return text if len(text) <= CLIP else text[:CLIP - 1].rstrip() + "…"


def _logical_lines(text: str) -> list[str]:
    """Lines with wrapped bullets joined: an indented, non-bullet line continues the one above."""
    out: list[str] = []
    for line in text.splitlines():
        cont = (line[:1].isspace() and line.strip() and not BULLET.match(line)
                and out and out[-1].strip() and not out[-1].lstrip().startswith("#"))
        if cont:
            out[-1] = out[-1].rstrip() + " " + line.strip()
        else:
            out.append(line)
    return out


def parse_status(text: str) -> dict:
    """{'stands', 'stands_date', 'next'} from one STATUS.md; None where absent."""
    stands = stands_date = nxt = None
    section = ""
    for line in _logical_lines(text):
        heading = re.match(r"^(#{2,6})\s+(.*)$", line)
        if heading and len(heading.group(1)) == 2:     # ### inside Next stays in Next
            section = heading.group(2).strip().lower()
        in_next = section.startswith("next")
        if in_next and not heading and nxt is None:
            item = BULLET.sub("", line, count=1).strip()
            if item and item not in ("—", "-") and not item.startswith("~~"):   # ~~struck~~ = done
                nxt = _clean(item)
        if section.startswith(NOT_PROGRESS) and not (heading and DATED.match(line)):
            continue
        m = DATED.match(line)
        if m and (stands_date is None or m.group(1) >= stands_date):   # last one wins a tie
            stands_date, stands = m.group(1), _clean(m.group(2))
    return {"stands": stands, "stands_date": stands_date, "next": nxt}


def _when(e: dict) -> _dt.datetime:
    try:
        return _dt.datetime.fromisoformat(e["when"])
    except (KeyError, ValueError):
        return _dt.datetime.min.replace(tzinfo=_dt.timezone.utc)


def last_touched(registry: dict, ledger: list[dict]) -> dict[str, dict]:
    """project name -> newest ledger entry for it."""
    idx = landed.project_index(registry)
    best: dict[str, dict] = {}
    for e in ledger:
        name = landed.project_for(e, idx)
        if name not in best or _when(e) > _when(best[name]):
            best[name] = e
    return best


def next_due(charter: dict | None) -> tuple[str | None, str | None]:
    """(date, what) of the earliest undone charter step, else finish_by; the board's hard date."""
    if not charter:
        return None, None
    open_steps = sorted((s["due"], s.get("name", "step")) for s in charter.get("steps", [])
                        if s.get("due") and not s.get("done") and not s.get("skipped"))
    if open_steps:
        return open_steps[0]
    return (charter["finish_by"], "finish by") if charter.get("finish_by") else (None, None)


def build_cards(registry: dict, dev_root: Path, ledger: list[dict]) -> dict[str, dict]:
    """Resume card per live project (retired rows get none)."""
    touched = last_touched(registry, ledger)
    out = {}
    for p in registry.get("projects", []):
        if p.get("status") in ARCHIVED:
            continue
        parsed = {"stands": None, "stands_date": None, "next": None}
        if p.get("dev_folder"):
            try:
                text = (Path(dev_root) / p["dev_folder"] / "docs" / "STATUS.md").read_text(
                    encoding="utf-8", errors="ignore")
                parsed = parse_status(text)
            except OSError:
                pass
        card = dict(parsed, next_from="status" if parsed["next"] else None)
        if not card["next"] and (p.get("next_action") or "").strip():
            card["next"], card["next_from"] = _clean(p["next_action"]), "registry"
        if not card["stands"] and p.get("updates"):
            card["stands_date"], card["stands"] = p["updates"][0].get("date"), _clean(p["updates"][0].get("note", ""))
        card["due"], card["due_what"] = next_due(p.get("charter"))
        e = touched.get(p["name"])
        card["touched"] = e["when"] if e else None
        card["touched_on"] = e.get("machine") if e else None
        out[p["name"]] = card
    return out

