"""The 7-day rule: a project started must prove itself within a week, or it is paused.

Decided 2026-10-03 (Eric). "Proved" = a named receiver AND its first step done (charter
step 1 for job work, `first_step_done` for anything without a charter). Covers job, side
and tool rows; system and knowledge rows are infrastructure, not starts. Rows active on
2026-10-03 were grandfathered (`seven_day_exempt`); reactivating any row restarts the
clock and drops that exemption (board_ops.patch_project).

The clock is `started`: stamped when a row becomes active. `slate.check` carries the
countdown from day 5 so `/slate` and the status line show it; `apply` pauses, and is run
by dev-sync and closeout through `portfolio.py seven-day --apply`. Like slate.py, `check`
never writes.
"""

from __future__ import annotations

import datetime as _dt

WINDOW_DAYS = 7
WARN_FROM_DAY = 5
COVERED_LANES = {"job", "side", "tool"}


def _date(value) -> _dt.date | None:
    try:
        return _dt.date.fromisoformat(value) if isinstance(value, str) else None
    except ValueError:
        return None


def receiver(p: dict) -> str:
    return str(p.get("receiver") or (p.get("charter") or {}).get("receiver") or "").strip()


def first_step_done(p: dict) -> bool:
    if p.get("first_step_done"):
        return True
    steps = (p.get("charter") or {}).get("steps") or []
    return bool(steps and steps[0].get("done"))


def proved(p: dict) -> bool:
    return bool(receiver(p)) and first_step_done(p)


def _on_the_clock(p: dict) -> bool:
    return (p.get("status") == "active" and p.get("lane") in COVERED_LANES
            and not p.get("seven_day_exempt") and not proved(p))


def check(data: dict, today: _dt.date) -> list[dict]:
    """Problems in slate.check's shape: DUE from day 5, OVERDUE past day 7."""
    out = []
    for p in data.get("projects", []):
        started = _date(p.get("started"))
        if not started or not _on_the_clock(p):
            continue
        age = (today - started).days
        missing = " and ".join(x for x, ok in (("a receiver", receiver(p)), ("step 1 done", first_step_done(p))) if not ok)
        if age > WINDOW_DAYS:
            out.append({"level": "OVERDUE", "project": p["name"],
                        "message": f"7-day rule: started {started}, still needs {missing} - pauses at the next sync"})
        elif age >= WARN_FROM_DAY:
            left = WINDOW_DAYS - age
            out.append({"level": "DUE", "project": p["name"],
                        "message": f"7-day rule: {left} day{'s' if left != 1 else ''} left to get {missing}"})
    return out


def apply(data: dict, today: _dt.date) -> list[str]:
    """Pause every row past its window. Returns the names paused."""
    paused = []
    expired = {p["project"] for p in check(data, today) if p["level"] == "OVERDUE"}
    for p in data.get("projects", []):
        if p["name"] in expired:
            p["status"] = "paused"
            p.setdefault("updates", []).insert(0, {
                "date": today.isoformat(),
                "note": f"[7-day rule] paused: started {p.get('started')}, no receiver + step 1 within {WINDOW_DAYS} days. "
                        "Set it active again to restart the clock."})
            paused.append(p["name"])
    return paused


def stamp_started(data: dict, today: _dt.date) -> None:
    """Give every active, covered row without a start date one (today)."""
    for p in data.get("projects", []):
        if p.get("status") == "active" and p.get("lane") in COVERED_LANES and not p.get("started"):
            p["started"] = today.isoformat()
def check(data: dict, today: _dt.date) -> dict:
    cfg = (data.get("meta") or {}).get("slate")
    if not isinstance(cfg, dict):
        return {"status": "OK", "enabled": False, "active": 0, "cap": None, "problems": []}

    cap = cfg.get("cap")
    close = parse_date(cfg.get("semester_close"))
    problems: list[dict] = []

    def add(level, project, message):
        problems.append({"level": level, "project": project, "message": message})

    active = [p for p in data.get("projects", [])
              if p.get("lane") == "job" and p.get("status") == "active"]

    if isinstance(cap, int) and len(active) > cap:
        add("OVERDUE", "(slate)",
            f"{len(active)} active job projects, cap is {cap} - finish or park one before anything else")

    for p in active:
        name = p.get("name", "<unnamed>")
        if args.command == "crosswalk":
            import crosswalk  # lazy, same reason as slate-check
            path = Path(args.registry) if args.registry else registry_path
            dev_root = Path(args.dev_root) if args.dev_root else registry_path.parent.parent
            drive_root = Path(args.drive_root) if args.drive_root else crosswalk.default_drive_root()
            result = crosswalk.check(load_registry(path), dev_root, drive_root)
            print(json.dumps(result, indent=2) if args.json else crosswalk.format_report(result))
            return 0
        data = load_registry(registry_path)
        if args.command == "seven-day":
            import seven_day
            today = _dt.date.fromisoformat(args.today) if args.today else _dt.date.today()
            before = json.dumps(data, sort_keys=True)
            seven_day.stamp_started(data, today)
            paused = seven_day.apply(data, today) if args.apply else []
            problems = seven_day.check(data, today)
            if json.dumps(data, sort_keys=True) != before:
                save_registry(registry_path, data)
            if args.json:
                print(json.dumps({"paused": paused, "problems": problems}, indent=2))
            else:
                print(f"7-day rule: {len(paused)} paused, {len(problems)} on the clock")
                for n in paused:
                    print(f"  PAUSED   {n}")
                for p in problems:
                    print(f"  {p['level']:<8} {p['project']}: {p['message']}")

