def unpushed_edits(repo: Path) -> int | None:
    """Registry edits not on GitHub yet: 1 if portfolio.json is dirty, plus unpushed commits
    touching it. None when the repo is not a git checkout. closeout clears them with a
    `data: board edits <date>` commit and a push (PM design Decision 10)."""
    def git(*a):
        return subprocess.run(["git", *a], cwd=repo, capture_output=True, text=True, timeout=10)
    try:
        dirty = git("status", "--porcelain", "--", "portfolio.json")
        if dirty.returncode != 0:
            return None
        ahead = git("rev-list", "--count", "@{u}..HEAD", "--", "portfolio.json")
        n = int(ahead.stdout.strip()) if ahead.returncode == 0 else 0   # no upstream: count dirty only
        return n + (1 if dirty.stdout.strip() else 0)
    except (OSError, ValueError, subprocess.SubprocessError):
        return None


