   portfolio (the static dashboard retired 2026-10-03): Baylor green turf, black
   broadcast cards, gold for progress/identity/active only, flag red as the single alarm. */
:root{
  --field-black:#0a0d0b; --bug-panel:#111613; --bug-edge:#1e2620;
  --baylor-green:#154734; --deep-turf:#0f3626; --green-line:#205540;
  --gold:#ffb81c; --deep-gold:#cf9410; --ink-on-gold:#171207;
  --chalk:#f4f6f3; --sideline-mist:#bad2c6; --faint-mist:#84a394;
  --flag-red:#ff5147; --track:#0c2118;
  --display:ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;
  --prose:ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;
}
/* No light theme, by decision — a broadcast graphic doesn't get one. */
html{color-scheme:dark}
*{box-sizing:border-box}
body{margin:0;background:var(--field-black);color:var(--chalk);
     font:13px/1.5 var(--prose)}

/* ---------- masthead ---------- */
header{display:flex;gap:14px;align-items:center;padding:13px 18px;
       background:var(--bug-panel);border-bottom:1px solid var(--bug-edge)}
h1{margin:0;font:600 21px/1 var(--display);}
h1 em{font-style:normal;color:var(--gold)}
#meta{font:600 11px/1 var(--display);
      color:var(--faint-mist);font-variant-numeric:tabular-nums}
.tabs{display:flex;gap:6px;margin-left:auto}
.tab,button.plain{font:600 11.5px/1 var(--display);
      cursor:pointer;border-radius:3px;padding:7px 15px;
      background:transparent;color:var(--sideline-mist);
      border:1px solid var(--green-line);transition:color .16s,border-color .16s}
.tab:hover,button.plain:hover{color:var(--chalk);border-color:var(--sideline-mist)}
.tab.on{background:var(--gold);border-color:var(--gold);color:var(--ink-on-gold)}
.tab.on:hover{color:var(--ink-on-gold)}
:focus-visible{outline:2px solid var(--gold);outline-offset:2px}
#nudge{display:flex;gap:10px;font:600 11px/1 var(--display);
      color:var(--sideline-mist)}
#nudge span{border:1px solid var(--green-line);border-radius:3px;padding:5px 8px}
#q{background:var(--field-black);color:var(--chalk);border:1px solid var(--green-line);
   border-radius:3px;padding:6px 10px;font:400 12.5px/1 var(--prose);width:200px;margin-left:auto}
#q:focus{border-color:var(--sideline-mist);outline:none}
#q + button + .tabs{margin-left:0}
.tab .n{opacity:.7;margin-left:5px;font-variant-numeric:tabular-nums}
.hidden-note{font:400 11.5px/1.4 var(--prose);color:var(--faint-mist);padding:3px 2px}

/* ---------- the turf ---------- */
/* Baylor green is one continuous field under every column, not eight saturated
   blocks — that keeps the 30-60% green commitment while the black cards stay the
   things you actually read. */
.cols{display:flex;padding:0;overflow-x:auto;align-items:stretch;
      background:var(--baylor-green);min-height:calc(100vh - 51px)}
.col{min-width:252px;width:252px;flex:0 0 auto;
     border-right:1px solid var(--green-line);display:flex;flex-direction:column}
.col>h2{margin:0;padding:11px 13px;display:flex;justify-content:space-between;
        gap:8px;align-items:baseline;background:var(--deep-turf);
        border-bottom:2px solid var(--gold);
        font:600 12px/1 var(--display);
        color:var(--chalk)}
.col>h2 .n{color:var(--gold);font-variant-numeric:tabular-nums;}
.drop{padding:11px;display:flex;flex-direction:column;gap:9px;flex:1;
      transition:background .16s}
.col.over .drop{background:#1c5a43}
.col.over>h2{border-bottom-color:var(--chalk)}
/* the inbox and the archive are not stages: mark them by surface, not by hue */
.col.inbox{background:var(--bug-panel);border-right:1px solid var(--bug-edge)}
.col.inbox>h2{background:#0d120f;border-bottom-color:var(--sideline-mist)}
.col.inbox>h2 .n{color:var(--sideline-mist)}
.col.archive{background:#0d1b15}
.col.archive>h2{background:#0b1712;border-bottom-color:var(--green-line)}
.col.archive>h2 .n{color:var(--faint-mist)}
.empty{font:400 12px/1.4 var(--prose);color:var(--faint-mist);opacity:.6;
       padding:3px 2px;font-style:italic}

/* ---------- cards ---------- */
.card{background:var(--bug-panel);border:1px solid var(--bug-edge);border-radius:8px;
      padding:10px 11px;cursor:grab;position:relative;overflow:hidden;
      box-shadow:0 2px 0 rgba(0,0,0,.45),0 14px 30px -22px rgba(0,0,0,.8);
      transition:border-color .16s,transform .16s}
.card:hover{border-color:var(--green-line);transform:translateY(-1px)}
.card.open{cursor:default;transform:none;border-color:var(--green-line)}
.card.dragging{opacity:.4}
/* The gold left bar is the system's signature mark, so it stays rare: only the
   #1 card in the lane gets it. On every card it would be wallpaper, and gold
   would stop meaning "this is the one." */
.card.front::before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;
      background:var(--gold)}
.card.front{padding-left:15px}

.nm{display:flex;gap:9px;align-items:flex-start}
.rk{font:600 17px/1 var(--display);color:var(--gold);font-variant-numeric:tabular-nums;
    flex:0 0 auto;min-width:15px;padding-top:1px}
.card.archived .rk{color:var(--faint-mist)}
h3{margin:0;flex:1;min-width:0;font:600 14px/1.25 var(--display);
   color:var(--chalk);
   /* names are one unbroken word joined by underscores; <wbr> marks the joins so a
      break lands there instead of mid-syllable. break-word is the last resort for a
      single segment longer than the column. */
   overflow-wrap:break-word}
.card.archived h3{color:var(--sideline-mist)}
.purpose{margin:7px 0 0;font:400 12.5px/1.45 var(--prose);color:var(--sideline-mist);
      display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.purpose.none{color:var(--faint-mist);font-style:italic;opacity:.75}

/* status pill — native select, system colors. The four DESIGN.md variants. */
select.st{flex:0 0 auto;appearance:none;-webkit-appearance:none;
      font:600 10.5px/1 var(--display);
      padding:3px 7px;border-radius:3px;cursor:pointer;
      background:transparent;color:var(--sideline-mist);
      border:none;box-shadow:inset 0 0 0 1px var(--green-line);
      transition:box-shadow .16s}
select.st option{background:var(--bug-panel);color:var(--chalk);font-family:var(--prose)}
select.st-active{background:var(--gold);color:var(--ink-on-gold);box-shadow:none}
select.st-paused{color:var(--sideline-mist);box-shadow:inset 0 0 0 1px var(--sideline-mist)}
select.st-dropped{color:var(--flag-red);box-shadow:inset 0 0 0 1px var(--flag-red)}
select.st-done{background:var(--deep-turf);color:var(--sideline-mist);
      box-shadow:inset 0 0 0 1px var(--green-line)}

/* stage readout — the LED strip, the system's second signature geometry */
.stage{display:flex;gap:7px;align-items:center;margin-top:9px}
.stage select.st{margin-left:auto}
.leds{display:flex;gap:2px;flex:0 0 auto}
.leds i{display:block;width:11px;height:6px;border-radius:2px;background:var(--track);
      box-shadow:inset 0 0 0 1px rgba(255,255,255,.07);
      transition:background .22s cubic-bezier(.22,1,.36,1)}
.leds i.on{background:linear-gradient(180deg,var(--gold),var(--deep-gold));box-shadow:none}
.card.archived .leds i.on{background:var(--green-line)}
.stage b{font:600 10.5px/1 var(--display);

